int romanToInt(string s) {
    unordered_map<char, int> m = {
        {'I',1},{'V',5},{'X',10},{'L',50},{'C',100},{'D',500},{'M',1000}
    };
    int ans = 0;
    for (int i = 0; i < s.size(); i++) {
        if (i + 1 < s.size() && m[s[i]] < m[s[i+1]]) {
            ans -= m[s[i]];
        } else {
            ans += m[s[i]];
        }
    }
    return ans;
}
// 核心洞察：小值在大值前→做减法 | 否则做加法
